<?php require __DIR__.'/lib.php';need_admin();$types=sections();$type=(string)($_GET['type']??'dashboard');if(!isset($types[$type])&&!in_array($type,['dashboard','wilayah','appearance','portal','service_cms','pages_cms','code_view','waris','mobile_chat'],true))$type='dashboard';$notice='';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$action=(string)($_POST['action']??'');$all=db_read('content');if($action==='save'){$id=trim((string)($_POST['id']??''));$entryType=(string)($_POST['type']??'berita');$title=trim((string)($_POST['title']??''));$body=trim((string)($_POST['body']??''));$link=trim((string)($_POST['link']??''));$image=trim((string)($_POST['old_image']??''));if(!isset($types[$entryType])||$title===''||strlen($title)>200){$error='Jenis konten atau judul tidak valid.';}elseif($link!==''&&(!filter_var($link,FILTER_VALIDATE_URL)||!in_array(parse_url($link,PHP_URL_SCHEME),['http','https'],true))){$error='Tautan harus memakai http atau https.';}else{if(isset($_FILES['image'])&&$_FILES['image']['error']!==UPLOAD_ERR_NO_FILE){$f=$_FILES['image'];if($f['error']!==UPLOAD_ERR_OK||$f['size']>4*1024*1024){$error='Upload gagal atau file melebihi 4 MB.';}else{$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??null;if(!$ext){$error='Foto harus JPG, PNG, atau WebP.';}else{$file='assets/images/upload-'.bin2hex(random_bytes(12)).'.'.$ext;if(!move_uploaded_file($f['tmp_name'],__DIR__.'/'.$file))$error='Folder assets/images tidak bisa ditulis.';else $image=$file;}}}if(!$error){$id=$id?:bin2hex(random_bytes(12));$exists=false;foreach($all as &$row){if($row['id']===$id){$row=['id'=>$id,'type'=>$entryType,'title'=>$title,'body'=>$body,'link'=>$link,'image'=>$image,'created_at'=>$row['created_at']??date('Y-m-d H:i:s')];$exists=true;break;}}unset($row);if(!$exists)$all[]=['id'=>$id,'type'=>$entryType,'title'=>$title,'body'=>$body,'link'=>$link,'image'=>$image,'created_at'=>date('Y-m-d H:i:s')];if(db_write('content',$all)){header('Location: '.url('admin.php?type='.$entryType.'&saved=1'));exit;}$error='Gagal menyimpan. Cek permission folder data.';}}}elseif($action==='delete'){$id=(string)($_POST['id']??'');$all=array_values(array_filter($all,fn($r)=>($r['id']??'')!==$id));if(db_write('content',$all)){header('Location: '.url('admin.php?type='.urlencode($type).'&deleted=1'));exit;}$error='Tidak dapat menghapus data.';}}
$all=db_read('content');$editing=null;if(!empty($_GET['edit']))foreach($all as $v)if($v['id']===$_GET['edit']){$editing=$v;break;}if(isset($_GET['saved']))$notice='Konten berhasil disimpan.';if(isset($_GET['deleted']))$notice='Konten berhasil dihapus.';$counts=[];foreach($types as $k=>$v)$counts[$k]=count(entries($k));head_html('Dashboard Admin');?><div class="admin-layout"><aside class="sidebar"><a class="side-brand" href="<?=esc(url())?>"><img src="<?=esc(ap_logo())?>" alt=""><span><b>Kelurahan Cikoko</b><small>Administrator Website</small></span></a><div class="side-nav"><a class="<?=$type==='dashboard'?'selected':''?>" href="<?=esc(url('admin.php'))?>">▦ &nbsp; Dashboard</a><?php foreach($types as $k=>$v):?><a class="<?=$type===$k?'selected':''?>" href="<?=esc(url('admin.php?type='.$k))?>">◫ &nbsp; <?=esc($v)?></a><?php endforeach;?><a class="<?=$type==='code_view'?'selected':''?>" href="<?=esc(url('admin.php?type=code_view'))?>">⌘ &nbsp; CMS Code View</a><a class="<?=$type==='pages_cms'?'selected':''?>" href="<?=esc(url('admin.php?type=pages_cms'))?>">▤ &nbsp; CMS Halaman Website</a><a class="<?=$type==='service_cms'?'selected':''?>" href="<?=esc(url('admin.php?type=service_cms'))?>">▤ &nbsp; CMS Detail Layanan</a><a class="<?=$type==='wilayah'?'selected':''?>" href="<?=esc(url('admin.php?type=wilayah'))?>">⌖ &nbsp; Peta & Data Wilayah</a><a class="<?=$type==='appearance'?'selected':''?>" href="<?=esc(url('admin.php?type=appearance'))?>">◈ &nbsp; Pengaturan Tampilan</a><a class="<?=$type==='portal'?'selected':''?>" href="<?=esc(url('admin.php?type=portal'))?>">♙ &nbsp; Akun Petugas & Bagian</a><a class="<?=$type==='waris'?'selected':''?>" href="<?=esc(url('admin.php?type=waris'))?>">▤ &nbsp; Verifikasi Ahli Waris</a><a class="<?=$type==='mobile_chat'?'selected':''?>" href="<?=esc(url('admin.php?type=mobile_chat'))?>">☏ &nbsp; Hubungi Kami · Chat</a><a href="<?=esc(url('kelola-inovasi.php'))?>">✦ &nbsp; Kelola Inovasi</a><a href="<?=esc(url('kelola-berita-galeri