uted">Kelola konten <?=esc(strtolower($types[$type]))?>.</p><a class="btn" href="<?=esc(url('admin.php?type='.$type.'&new=1#editor'))?>">+ Tambah Konten</a></div><div class="admin-box table-scroll"><table class="admin-table"><thead><tr><th>Konten</th><th>Tanggal</th><th>Aksi</th></tr></thead><tbody><?php foreach(entries($type) as $item):?><tr><td><strong><?=esc($item['title'])?></strong><small><?=esc(excerpt($item['body'],70))?></small></td><td><?=esc(date('d M Y',strtotime($item['created_at'])))?></td><td><div class="table-actions"><a class="btn small" href="<?=esc(url('admin.php?type='.$type.'&edit='.$item['id'].'#editor'))?>">Edit</a><form method="post" onsubmit="return confirm('Hapus konten ini secara permanen?')"><input type="hidden" name="csrf" value="<?=esc(csrf())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=esc($item['id'])?>"><button class="btn small danger">Hapus</button></form></div></td></tr><?php endforeach;?></tbody></table><?php if(!$counts[$type]):?><p>Belum ada data.</p><?php endif;?></div><?php if($editing||isset($_GET['new'])):?><div class="admin-box editor" id="editor"><h3><?= $editing?'Edit Konten':'Tambah Konten'?></h3><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=esc(csrf())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=esc($editing['id']??'')?>"><input type="hidden" name="type" value="<?=esc($type)?>"><input type="hidden" name="old_image" value="<?=esc($editing['image']??'')?>"><label>Judul<input name="title" maxlength="200" required value="<?=esc($editing['title']??'')?>"></label><label>Deskripsi / Isi<textarea name="body" rows="6" required><?=esc($editing['body']??'')?></textarea></label><label>Foto (JPG, PNG, WebP; maksimal 4 MB)<input type="file" name="image" accept="image/jpeg,image/png,image/webp"></label><?php if(!empty($editing['image'])):?><img class="edit-preview" src="<?=esc(url($editing['image']))?>" alt="Foto konten saat ini"><?php endif;?><label>URL tujuan (opsional, khususnya layanan)<input name="link" type="url" placeholder="https://..." value="<?=esc($editing['link']??'')?>"></label><div class="form-actions"><button class="btn">Simpan Konten</button><a href="<?=esc(url('admin.php?type='.$type))?>" class="btn btn-secondary">Batal</a></div></form></div><?php endif;?><?php endif;?></div></div></div><script src="<?=esc(url('assets/app.js'))?>" defer></script></body></html>
